      const info = JSON.parse(readFileSync(path.join(fixture.root, "dist/BUILD_INFO.json"), "utf8"));
      const outputTree = JSON.parse(readFileSync(path.join(fixture.root, "dist/PLATFORM_BUILD_OUTPUT_TREE.json"), "utf8"));
